---

### 📄 `routes/upload.js` (File Upload Route)

```js
const express = require('express');
const router = express.Router();
const multer = require('multer');
const bcrypt = require('bcrypt');
const s3 = require('../config/s3');
const db = require('../config/db');
require('dotenv').config();

// Multer setup for handling multipart/form-data
const storage = multer.memoryStorage();
const upload = multer({ storage });

// Authentication middleware
const authenticate = (req, res, next) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password are required' });
  }

  const validPassword = bcrypt.compareSync(password, process.env.ADMIN_PASSWORD_HASH);

  if (username !== process.env.ADMIN_USERNAME || !validPassword) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  next();
};

// Upload route
router.post('/upload', authenticate, upload.fields([
  { name: 'imageHD', maxCount: 1 },
  { name: 'imageCompresse', maxCount: 1 }
]), async (req, res) => {
  const { title } = req.body;
  const files = req.files;

  if (!files.imageHD || !files.imageCompresse) {
    return res.status(400).json({ error: 'Both imageHD and imageCompresse are required' });
  }

  const uploadToS3 = (file, key) => {
    const params = {
      Bucket: process.env.S3_BUCKET,
      Key: key,
      Body: file.buffer,
      ContentType: file.mimetype,
      ACL: 'public-read'
    };

    return new Promise((resolve, reject) => {
      s3.upload(params, (err, data) => {
        if (err) return reject(err);
        resolve(data.Location);
      });
    });
  };

  try {
    const urlHD = await uploadToS3(files.imageHD[0], `images/hd/${Date.now()}-${files.imageHD[0].originalname}`);
    const urlCompresse = await uploadToS3(files.imageCompresse[0], `images/compressed/${Date.now()}-${files.imageCompresse[0].originalname}`);

    const query = 'INSERT INTO Galerie (title, imageHD, imageCompresse) VALUES (?, ?, ?)';
    await db.query(query, [title, urlHD, urlCompresse]);

    res.status(201).json({ message: 'Upload successful', urls: { hd: urlHD, compressed: urlCompresse } });

  } catch (error) {
    console.error('Error uploading files:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

module.exports = router;
```

---

